ALTER TABLE "matches" ADD CONSTRAINT "matches_completed_score_shape" CHECK ("matches"."status" <> 'completed' or ("matches"."completed_at" is not null and "matches"."winner" is not null and "matches"."player1_battle_points" is not null and "matches"."player2_battle_points" is not null and "matches"."player1_challenge_points" is not null and "matches"."player2_challenge_points" is not null and "matches"."player1_total" is not null and "matches"."player2_total" is not null and "matches"."round_winners" is not null and jsonb_array_length("matches"."round_winners") between 2 and 3 and (("matches"."player1_battle_points" = 2 and "matches"."player2_battle_points" in (0, 1) and "matches"."winner" = 'player1') or ("matches"."player2_battle_points" = 2 and "matches"."player1_battle_points" in (0, 1) and "matches"."winner" = 'player2'))));